mapper.update:
UPDATE management_task_item
SET status = 'CANCELLED', lock_key = NULL, completed_at = #{completedAt}, updated_at = #{updatedAt}
WHERE task_id = #{taskId} AND status = 'QUEUED'

UPDATE management_task_item
SET status = 'QUEUED', attempt = #{attempt}, progress = 0, error_message = NULL,
    started_at = NULL, completed_at = NULL, lock_key = #{lockKey}, updated_at = #{updatedAt}
WHERE id = #{itemId}

UPDATE management_task_item
SET status = #{newStatus}, updated_at = #{updatedAt}
, started_at = #{startedAt}
, completed_at = #{completedAt}, lock_key = NULL
, error_message = #{errorMessage}
, result_ref_type = #{resultRefType}
, result_ref_id = #{resultRefId}
WHERE id = #{itemId}
  AND status NOT IN ('SUCCEEDED', 'PARTIALLY_SUCCEEDED', 'FAILED', 'CANCELLED')
  AND attempt IS NULLAND attempt = #{attempt}

UPDATE management_task_item
SET progress = #{progress}, updated_at = #{updatedAt}
, status = 'RUNNING', started_at = #{startedAt}
WHERE id = #{itemId}
  AND status NOT IN ('SUCCEEDED', 'PARTIALLY_SUCCEEDED', 'FAILED', 'CANCELLED')
  AND attempt IS NULLAND attempt = #{attempt}
